return {["fb13_01"]={["dsc"]=[[嵩山古称方外，又称崇山，为五岳中的中岳，由太室少室二山沿绵而成。汉武帝时称“嵩高”，取自诗经“嵩岳维高，峻极于天”，道教以之为第六小洞天。阕高丈余，南面刻“中岳太室阳城”六字，篆文古朴，苍劲有力。向西就是去少室山少林寺的路。向北一里许便是中岳庙了。]],["fightBackground"]=[[山外]],["id"]=[[fb13_01]],["name"]=[[太室阙]],["permission"]=2,["role1"]=[[fb13r01_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_02]]},["fb13_02"]={["down"]=[[fb13_01]],["dsc"]=[[天中阁是中岳庙的大门，原称黄中阁。庙内有古柏三百余株，金石碑碣百余座。庙前石翁仲，雕制古朴。南面是嵩山的出口太室阙。]],["fightBackground"]=[[山外]],["id"]=[[fb13_02]],["name"]=[[天中阁]],["permission"]=2,["role1"]=[[fb13r02_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_03]]},["fb13_03"]={["down"]=[[fb13_02]],["dsc"]=[[崇圣门前古神库有四座镇库铁人，高达丈许，振臂握拳，怒目挺胸，身姿雄健。向北就是中岳庙最大的殿宇中岳大殿了。]],["fightBackground"]=[[山外]],["id"]=[[fb13_03]],["item1"]=[[fb13item19]],["item2"]=[[fb13item19]],["item3"]=[[fb13item19]],["item4"]=[[fb13item19]],["name"]=[[崇圣门]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb13_04]]},["fb13_04"]={["down"]=[[fb13_03]],["dsc"]=[[大殿面阔九间，进深五间，重檐庑殿式屋顶，座落在七尺高的台基上，气势雄伟。大殿中供奉岳神天中王。]],["id"]=[[fb13_04]],["item1"]=[[fb13item17]],["name"]=[[中岳大殿]],["permission"]=2,["role1"]=[[fb13r04_1]],["role2"]=[[fb13r04_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_05]]},["fb13_05"]={["down"]=[[fb13_04]],["dsc"]=[[你走在嵩山中岳山道上，青松翠柏，山风岚雾，时来飘荡。左边通往启母石，右手是卢崖瀑布。]],["id"]=[[fb13_05]],["leftUp"]=[[fb13_08]],["name"]=[[中岳山道]],["permission"]=2,["rightDown"]=[[fb13_06]],["rightUp"]=[[fb13_18]],["role1"]=[[fb13r05_1]],["role2"]=[[fb13r05_2]],["role3"]=[[fb13r05_3]],["stepMusic"]=[[jiaobu]]},["fb13_06"]={["dsc"]=[[这理是嵩山东南的玉女台。玉女台下的石淙洞，就是“石淙会饮”之处。两岸石壁高耸，险峻如削，怪古嶙峋多姿，大小别致。涧中有巨石，两岸多洞穴，水声石响，淙淙有声，故名“石淙”。]],["fightBackground"]=[[山外]],["id"]=[[fb13_06]],["leftUp"]=[[fb13_05]],["name"]=[[玉女台]],["permission"]=2,["rightUp"]=[[fb13_75]],["role1"]=[[fb13r06_1]],["stepMusic"]=[[jiaobu]]},["fb13_07"]={["dsc"]=[[启母阙在嵩山南麓万岁峰下，是汉代启母庙前的神道阙，和太室阙同为中岳汉三阙之一。往南看去颖水横流，好一派“颖水春耕”的画卷。]],["fightBackground"]=[[山外]],["id"]=[[fb13_07]],["name"]=[[启母阙]],["permission"]=2,["right"]=[[fb13_08]],["role1"]=[[fb13r07_1]],["stepMusic"]=[[jiaobu]]},["fb13_08"]={["dsc"]=[[这里有一壁三丈巨石当道。相传大禹治水时要打通辕擐山，大禹化熊扒挖不止。禹妻涂山氏送饭时不慎撞破，失惊而逃，到此化石。其时涂山已有身孕，大禹追及唤子，巨石北裂一口，夏启呱呱落地。巨石因此唤作启母石。]],["fightBackground"]=[[山外]],["id"]=[[fb13_08]],["item1"]=[[fb13item8]],["left"]=[[fb13_07]],["name"]=[[启母石]],["permission"]=2,["rightDown"]=[[fb13_05]],["role1"]=[[fb13r08_1]],["role2"]=[[fb13r08_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_09]]},["fb13_09"]={["down"]=[[fb13_08]],["dsc"]=[[你走在嵩岳山道，青松翠柏，山风岚雾，时来飘荡。远望山下犬吠鸡啼，顿起仙凡之感。]],["fightBackground"]=[[山外]],["id"]=[[fb13_09]],["name"]=[[嵩岳山道]],["permission"]=2,["role1"]=[[fb13r09_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_10]]},["fb13_10"]={["down"]=[[fb13_09]],["dsc"]=[[这里原是嵩阳寺。现在文化昌明了，就改成了嵩阳书院，和睢阳书院，岳麓书院，白鹿书院合称天下“四大书院”。北宋程颐曾在此讲学。院内有古柏三株，汉武帝巡游至此，册封为大将军，二将军，三将军。]],["id"]=[[fb13_10]],["leftUp"]=[[fb13_11]],["name"]=[[嵩阳书院]],["permission"]=2,["role1"]=[[fb13r10_1]],["role2"]=[[fb13r10_2]],["role3"]=[[fb13r10_3]],["stepMusic"]=[[jiaobu]]},["fb13_11"]={["dsc"]=[[你走在嵩岳山道，青松翠柏，山风岚雾，时来飘荡。远望山下犬吠鸡啼，顿起仙凡之感。]],["fightBackground"]=[[山外]],["id"]=[[fb13_11]],["name"]=[[嵩岳山道]],["permission"]=2,["rightDown"]=[[fb13_10]],["role1"]=[[fb13r11_1]],["role2"]=[[fb13r11_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_12]]},["fb13_12"]={["down"]=[[fb13_11]],["dsc"]=[[这里原是北魏离宫。孝明帝舍为佛院，至隋方有今名，寺围阔大，僧舍连云。院内风动旌扬，松摇竹乱，别有一般清静。]],["id"]=[[fb13_12]],["item1"]=[[lbr12_1]],["item2"]=[[lbr12_2]],["item3"]=[[lbr12_3]],["left"]=[[fb13_13]],["leftUp"]=[[fb13_14]],["name"]=[[嵩岳寺]],["permission"]=2,["role1"]=[[fb13r12_1]],["role2"]=[[fb13r12_2]],["role3"]=[[fb13r12_3]],["role4"]=[[fb13r12_4]],["stepMusic"]=[[jiaobu]]},["fb13_13"]={["dsc"]=[[嵩岳寺塔为密檐式砖塔，高达十余丈，外廓十二面，内室八方四门，十五层密檐塔刹向上收紧，优美绝伦。]],["id"]=[[fb13_13]],["name"]=[[嵩岳寺塔]],["permission"]=2,["right"]=[[fb13_12]],["role1"]=[[fb13r13_1]],["stepMusic"]=[[jiaobu]]},["fb13_14"]={["dsc"]=[[你走在嵩岳山道，青松翠柏，山风岚雾，时来飘荡。远望山下犬吠鸡啼，顿起仙凡之感。]],["fightBackground"]=[[山外]],["id"]=[[fb13_14]],["name"]=[[嵩岳山道]],["permission"]=2,["rightDown"]=[[fb13_12]],["role1"]=[[fb13r14_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_15]]},["fb13_15"]={["down"]=[[fb13_14]],["dsc"]=[[法王寺在嵩山玉柱峰下，隐约于茂密松林中，背后是太室，两边有峻岭，好像一把椅子，古刹位于中间。法王寺建于东汉明帝永平十四年（公元七十一年），是佛教传入中国后建造最早的寺院，是汉明帝专为印度高僧摄摩腾和竺法兰译经传教而敕建的，成为中国第一所菩提道场，规模宏大，结构严谨，殿堂楼阁，金碧辉煌。]],["id"]=[[fb13_15]],["left"]=[[fb13_17]],["name"]=[[法王寺]],["permission"]=2,["rightUp"]=[[fb13_20]],["role1"]=[[fb13r15_1]],["role2"]=[[fb13r15_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_16]]},["fb13_16"]={["down"]=[[fb13_15]],["dsc"]=[[法王寺北山坡上，是法王寺塔院。院内有十五层密檐方塔，高近二十丈，造型优美。院内其它三座单檐墓塔，亦玲珑秀丽。]],["id"]=[[fb13_16]],["name"]=[[塔院]],["permission"]=2,["role1"]=[[fb13r16_1]],["stepMusic"]=[[jiaobu]]},["fb13_17"]={["dsc"]=[[里是法王寺的月台。从月台东望，太室山峦高耸入云，寺东有双峰插云，嶙峋崛突，相峙对立，中间阙如，其壮如门，故称“嵩门”。良夜长宵，正是饱览嵩山八景之“嵩门待月”和回味嵩门来历传说的好地方。晴天白日里，远眺少室山有时能看到同列嵩山八景的“少室晴雪”。]],["fightBackground"]=[[山外]],["id"]=[[fb13_17]],["name"]=[[月台]],["permission"]=2,["right"]=[[fb13_15]],["role1"]=[[fb13r17_1]],["role2"]=[[fb13r17_2]],["stepMusic"]=[[jiaobu]]},["fb13_18"]={["dsc"]=[[忽听水声如雷，悬练峰下一座高大的石崖峭壁上，两条玉龙直挂下来，双瀑并泄，屈曲回旋，飞跃奔逸，水花映日，淡淡冕生。唐玄宗年间，有一个被封为谏仪大夫的卢鸿乙，来此隐居，广招天下才子，在此讲学，此崖遂称为“卢崖”，鸿乙隐居处称为“早堂”。鸿乙仙游之后，玄宗改“草堂”为“卢崖寺”。嵩山八景的“卢崖瀑布”便在此间。]],["id"]=[[fb13_18]],["leftDown"]=[[fb13_05]],["name"]=[[卢崖寺]],["permission"]=2,["role1"]=[[fb13r18_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_19]]},["fb13_19"]={["down"]=[[fb13_18]],["dsc"]=[[由此上山，山路越发险竣。铁梁峡右侧尽是怪石，而左边则为万仞深谷，渺不见底。隔着峡谷，青冈峰环抱青冈坪，向上是嵩山主峰的山路。登高远眺石羊关，隐隐可见“玉溪垂钓”处。]],["id"]=[[fb13_19]],["name"]=[[铁梁峡]],["permission"]=2,["role1"]=[[fb13r19_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_20]]},["fb13_20"]={["down"]=[[fb13_19]],["dsc"]=[[你走在嵩山胜观峰山道上，遥望太室，少室两山间有一关口。那就是轩辕关。站在此处，正可饱览嵩山八景的“轩辕早行”。]],["fightBackground"]=[[山外]],["id"]=[[fb13_20]],["leftDown"]=[[fb13_15]],["name"]=[[胜观山道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb13_21]]},["fb13_21"]={["down"]=[[fb13_20]],["dsc"]=[[陡见双峰中断，天然出现一个门户，疾风从断绝处吹出，云雾随风扑面而至，这里就是朝天门了。天门望去，便见箕山。路人到此，感受山风送爽，亦不让“箕阴避暑”之处了。]],["fightBackground"]=[[山外]],["id"]=[[fb13_21]],["name"]=[[朝天门]],["permission"]=2,["role1"]=[[fb13r21_1]],["role2"]=[[fb13r21_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_22]]},["fb13_22"]={["down"]=[[fb13_21]],["dsc"]=[[你走在嵩山峻极山道上，青松翠柏，山风岚雾，时来飘荡。远望山下犬吠鸡啼，顿起仙凡之感。上面就是嵩山峻极禅院。]],["fightBackground"]=[[山外]],["id"]=[[fb13_22]],["name"]=[[峻极山道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb13_23]]},["fb13_23"]={["down"]=[[fb13_22]],["dsc"]=[[嵩山绝顶，古称“峻极”。极顶有一峻极禅院，本是佛教大寺，但百年来却已成为嵩山宗掌门人的住所。这里是峻极禅院山门，西上山路可以到达封禅台。]],["fightBackground"]=[[山外]],["id"]=[[fb13_23]],["leftUp"]=[[fb13_24]],["name"]=[[峻极山门]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb13_27]]},["fb13_24"]={["dsc"]=[[你走在嵩山极顶山道，青松翠柏，山风岚雾，时来飘荡。远望山下犬吠鸡啼，顿起仙凡之感。西上就是封禅台了。]],["fightBackground"]=[[山外]],["id"]=[[fb13_24]],["item1"]=[[ycitem1]],["leftUp"]=[[fb13_25]],["name"]=[[极顶山道]],["permission"]=2,["rightDown"]=[[fb13_23]],["role1"]=[[fb13r24_1]],["stepMusic"]=[[jiaobu]]},["fb13_25"]={["dsc"]=[[你走在嵩山极顶山道，青松翠柏，山风岚雾，时来飘荡。远望山下犬吠鸡啼，顿起仙凡之感。西上就是封禅台了。]],["fightBackground"]=[[山外]],["id"]=[[fb13_25]],["leftUp"]=[[fb13_26]],["name"]=[[极顶山道]],["permission"]=2,["rightDown"]=[[fb13_24]],["role1"]=[[fb13r25_1]],["stepMusic"]=[[jiaobu]]},["fb13_26"]={["dsc"]=[[峻极封禅台由大麻石所建，每块大石都凿得极是平整。地势甚为宽阔。这里独立天心，万峰在下，云开日朗，纤翳不生。极目北望，可遥见成皋玉门，黄河有如一线，西向隐隐见到洛阳伊阙，东南都是叠叠重山。]],["id"]=[[fb13_26]],["name"]=[[封禅台]],["permission"]=2,["rightDown"]=[[fb13_25]],["role1"]=[[fb13r26_1]],["role2"]=[[fb13r26_2]],["stepMusic"]=[[jiaobu]]},["fb13_27"]={["down"]=[[fb13_23]],["dsc"]=[[这里是峻极禅院山门内前庭。庭院中青石铺地、古柏森森，可容纳数百人集会。内里是禅院大殿，两厢是一些低矮小房。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb13_27]],["name"]=[[前庭]],["permission"]=1,["role1"]=[[fb13r27_1]],["role2"]=[[fb13r27_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_28]]},["fb13_28"]={["down"]=[[fb13_27]],["dsc"]=[[峻极禅院处嵩山绝顶，院中古柏森森，殿上并无佛像。院宇辽阔，可容千人。往里就是嵩山宗的本院了。]],["id"]=[[fb13_28]],["item1"]=[[bfitem1]],["item2"]=[[bfitem2]],["name"]=[[峻极禅院]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb13_29]]},["fb13_29"]={["down"]=[[fb13_28]],["dsc"]=[[这里是峻极禅院通往后庭的中门，门厚三寸，红松铜箍，门上两幅门神经多年风雨，多有剥落，现下颜色尚新，想来是嵩山宗新近油漆了的。外派人士到此就该回头了。]],["fightBackground"]=[[山外]],["id"]=[[fb13_29]],["name"]=[[中门]],["permission"]=1,["role1"]=[[fb13r29_1]],["role2"]=[[fb13r29_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_30]]},["fb13_30"]={["down"]=[[fb13_29]],["dsc"]=[[这里原来是峻极禅院的大雄宝殿，自五岳山宗百年前在此歃血为盟以来，这里就成了五岳山宗中枢所在了。堂上正中放着一张黄绸太师敞椅，那是盟主的宝座。两边雁形排列着泰、华、衡、恒的青呢、白缎、红罗、黑绫座椅，椅后插着各派的五色旗。]],["id"]=[[fb13_30]],["name"]=[[会盟堂]],["permission"]=1,["role1"]=[[fb13r30_1]],["role2"]=[[fb13r30_2]],["role3"]=[[fb13r30_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_35]]},["fb13_31"]={["dsc"]=[[这是嵩山宗的厨房，一位油光满面的伙夫正在烧火做饭。房间里散发着饭菜的香味。厨房里放着几张小桌椅，你可以向伙夫要些吃的喝的。]],["id"]=[[fb13_31]],["name"]=[[厨房]],["permission"]=2,["right"]=[[fb13_32]],["role1"]=[[fb13r31_1]],["stepMusic"]=[[jiaobu]]},["fb13_32"]={["down"]=[[fb13_33]],["dsc"]=[[这里是一个小小庭院，院子里常有嵩山弟子结伴往来。庭院四周矮墙下长着的小灌木里，偶尔冒出几星白色小花。鹅卵细石铺就的小路在灌木丛和长草间穿过。]],["id"]=[[fb13_32]],["left"]=[[fb13_31]],["name"]=[[西庭]],["permission"]=2,["right"]=[[fb13_34]],["role1"]=[[fb13r32_1]],["role2"]=[[fb13r32_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_41]]},["fb13_33"]={["dsc"]=[[这是一个仓库，四周密不透风。你一进门便闻到一股霉味，满屋的灰尘，成堆成堆的物品快堆满了整间房间。]],["id"]=[[fb13_33]],["item1"]=[[fb13item20]],["item2"]=[[fb13item21]],["item3"]=[[fb13item22]],["name"]=[[仓库]],["permission"]=1,["role1"]=[[fb13item100]],["role2"]=[[fb13item101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_32]]},["fb13_34"]={["dsc"]=[[这里是环绕池塘的走廊，画阑雕栋，却也美仑美奂。一路走来，脚底木板响动，别有韵味。嵩岳独立天心，八方天风，只吹得天边云起云落，满山树浪起伏。]],["id"]=[[fb13_34]],["left"]=[[fb13_32]],["name"]=[[西廊]],["permission"]=2,["right"]=[[fb13_35]],["role1"]=[[fb13r34_1]],["stepMusic"]=[[jiaobu]]},["fb13_35"]={["down"]=[[fb13_30]],["dsc"]=[[没有亲眼见到，没几个人会相信，在这嵩山绝顶之上，居然会有这么大一塘水。一柄长达五丈的铁剑凌空横卧水塘上，剑刃宽阔，剑尖非常锋锐，正是嵩山宗惯常使用的剑。水塘往北延伸。东西有长廊跨水而过。]],["id"]=[[fb13_35]],["item1"]=[[fb13item9]],["left"]=[[fb13_34]],["name"]=[[剑池]],["permission"]=1,["right"]=[[fb13_36]],["stepMusic"]=[[jiaobu]]},["fb13_36"]={["dsc"]=[[这里是环绕池塘的走廊，画阑雕栋，却也美仑美奂。一路走来，脚底木板响动，别有韵味。嵩岳独立天心，八方天风，只吹得天边云起云落，满山树浪起伏。]],["id"]=[[fb13_36]],["left"]=[[fb13_35]],["name"]=[[东廊]],["permission"]=1,["right"]=[[fb13_37]],["stepMusic"]=[[jiaobu]]},["fb13_37"]={["down"]=[[fb13_38]],["dsc"]=[[这里是一个小小庭院，院子里常有嵩山弟子结伴往来。庭院四周矮墙下长着的小灌木里，偶尔冒出几星白色小花。鹅卵细石铺就的小路在灌木丛和长草间穿过。]],["id"]=[[fb13_37]],["left"]=[[fb13_36]],["name"]=[[东庭]],["permission"]=1,["right"]=[[fb13_39]],["role1"]=[[fb13r37_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_42]]},["fb13_38"]={["dsc"]=[[这里是嵩山宗的书斋，靠墙是一排书架，上面整整齐齐码着一排排书，大略看去各派武籍都有。南侧靠窗处有张书桌，桌上四宝俱备。]],["id"]=[[fb13_38]],["item1"]=[[fb13item11]],["item2"]=[[fb13item12]],["item3"]=[[fb13item13]],["name"]=[[书斋]],["permission"]=2,["role1"]=[[fb13r38_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_37]]},["fb13_39"]={["dsc"]=[[这是一间净室，室内唯有一个壁橱。窗外偶尔光线斜入，映见正中梁顶似乎存放着一些物事。]],["id"]=[[fb13_39]],["item1"]=[[fb13item33]],["left"]=[[fb13_37]],["name"]=[[剑庐]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb13_40"]={["dsc"]=[[这里是嵩山宗练功房，地下凌乱地放着几个蒲团，几位嵩山弟子正盘膝坐在上面打坐。]],["id"]=[[fb13_40]],["name"]=[[练功房]],["permission"]=2,["right"]=[[fb13_41]],["role1"]=[[fb13r40_1]],["stepMusic"]=[[jiaobu]]},["fb13_41"]={["down"]=[[fb13_32]],["dsc"]=[[这里是环绕池塘的走廊，画阑雕栋，却也美仑美奂。一路走来，脚底木板响动，别有韵味。嵩岳独立天心，八方天风，只吹得天边云起云落，满山树浪起伏。]],["id"]=[[fb13_41]],["left"]=[[fb13_40]],["name"]=[[西廊]],["permission"]=2,["role1"]=[[fb13r41_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_44]]},["fb13_42"]={["down"]=[[fb13_37]],["dsc"]=[[这里是环绕池塘的走廊，画阑雕栋，却也美仑美奂。一路走来，脚底木板响动，别有韵味。嵩岳独立天心，八方天风，只吹得天边云起云落，满山树浪起伏。]],["id"]=[[fb13_42]],["name"]=[[东廊]],["permission"]=1,["right"]=[[fb13_43]],["role1"]=[[fb13r42_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_49]]},["fb13_43"]={["dsc"]=[[这是间整洁的厢房，是嵩山弟子休息起居的地方。因为门窗常年闭着，房间难免昏暗。房里靠窗处摆设桌椅，里边靠墙放着一张收拾得舒舒服服的大床，看着就让人想睡觉。]],["id"]=[[fb13_43]],["left"]=[[fb13_42]],["name"]=[[休息室]],["permission"]=1,["role1"]=[[fb13r43_1]],["role2"]=[[fb13r43_2]],["role3"]=[[fb13r43_3]],["stepMusic"]=[[jiaobu]]},["fb13_44"]={["down"]=[[fb13_41]],["dsc"]=[[这里是嵩山宗的练武场。地面是用黄泥土拌杂砂石砸实的，看起来很结实的样子。练武场中间安着些器械，看来是练功用的。一些嵩山弟子正满头臭汗地刻苦练功。]],["fightBackground"]=[[擂台]],["id"]=[[fb13_44]],["name"]=[[西武场]],["permission"]=2,["right"]=[[fb13_45]],["role1"]=[[fb13r44_1]],["role2"]=[[fb13r44_2]],["role3"]=[[fb13r44_3]],["stepMusic"]=[[jiaobu]]},["fb13_45"]={["dsc"]=[[这里是环绕池塘的走廊，画阑雕栋，却也美仑美奂。一路走来，脚底木板响动，别有韵味。嵩岳独立天心，八方天风，只吹得天边云起云落，满山树浪起伏。]],["id"]=[[fb13_45]],["left"]=[[fb13_44]],["name"]=[[西廊]],["permission"]=2,["right"]=[[fb13_46]],["stepMusic"]=[[jiaobu]]},["fb13_46"]={["down"]=[[fb13_47]],["dsc"]=[[这是一个小园子，三面池塘，北面通向后庭。园中栽着不少奇花异卉，山石古拙，显是花了不菲的精力和财力。几条碎石小路在茵茵草地和葱茏灌木中交叠，山风吹过，撒下一地花瓣。]],["id"]=[[fb13_46]],["left"]=[[fb13_45]],["name"]=[[花园]],["permission"]=1,["right"]=[[fb13_48]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_51]]},["fb13_47"]={["dsc"]=[[你扶着塘边的石栏杆往南望，可以看到剑池的那口大铁剑，回身就是小花园了。嵩岳绝顶，天风浩荡，吹皱一池碧水，大略韵味如此。]],["id"]=[[fb13_47]],["name"]=[[池塘]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb13_46]]},["fb13_48"]={["dsc"]=[[这里是环绕池塘的走廊，画阑雕栋，却也美仑美奂。一路走来，脚底木板响动，别有韵味。嵩岳独立天心，八方天风，只吹得天边云起云落，满山树浪起伏。]],["id"]=[[fb13_48]],["left"]=[[fb13_46]],["name"]=[[东廊]],["permission"]=1,["right"]=[[fb13_49]],["stepMusic"]=[[jiaobu]]},["fb13_49"]={["down"]=[[fb13_42]],["dsc"]=[[这里是嵩山宗的练武场。地面是用黄泥土拌杂砂石砸实的，看起来很结实的样子。练武场中间安着些器械，看来是练功用的。一些嵩山宗弟子正满头臭汗地刻苦练功。]],["fightBackground"]=[[擂台]],["id"]=[[fb13_49]],["left"]=[[fb13_48]],["name"]=[[东武场]],["permission"]=1,["role1"]=[[fb13r49_1]],["role2"]=[[fb13r49_2]],["stepMusic"]=[[jiaobu]]},["fb13_50"]={["dsc"]=[[这是一间丹房，房间内飘着一股药香味，似乎有人经常在这里炼丹。]],["id"]=[[fb13_50]],["item1"]=[[fb13item14]],["name"]=[[丹房]],["permission"]=2,["right"]=[[fb13_51]],["role1"]=[[fb13r50_100]],["stepMusic"]=[[jiaobu]]},["fb13_51"]={["down"]=[[fb13_46]],["dsc"]=[[这里是峻极禅院花院内的后庭。庭院中青石铺地、古柏森森，四周是本派首脑人物的起居之处，向来少有人来。北面是独尊坛。]],["id"]=[[fb13_51]],["left"]=[[fb13_50]],["name"]=[[后庭]],["permission"]=1,["right"]=[[fb13_52]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_53]]},["fb13_52"]={["dsc"]=[[你走进了一间卧室。一种非常清亮的感觉扑面而来。琴剑书画，挂在墙上。窗明几净，一切都井井有条。右首一张床，床上一条黄缎被，看起来很是舒适。]],["id"]=[[fb13_52]],["left"]=[[fb13_51]],["name"]=[[卧室]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb13_53"]={["down"]=[[fb13_51]],["dsc"]=[[这里是独尊坛。向来五岳以泰山为尊，但嵩山弟子一心向道，求知求真，在嵩山设下此坛，开坛作法，以祭天地。这里陈列华贵，雕梁画栋，也着实花了不少心力。]],["fightBackground"]=[[擂台]],["id"]=[[fb13_53]],["item1"]=[[fb13item24]],["name"]=[[独尊坛]],["permission"]=1,["role1"]=[[fb13r53_1a]],["stepMusic"]=[[jiaobu]]},["fb13_54"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb13_54]],["item1"]=[[fb13item29]],["name"]=[[密道]],["permission"]=1,["right"]=[[fb13_55]],["stepMusic"]=[[jiaobu]]},["fb13_55"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb13_55]],["left"]=[[fb13_54]],["name"]=[[密道]],["permission"]=1,["right"]=[[fb13_56]],["stepMusic"]=[[jiaobu]]},["fb13_56"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb13_56]],["item1"]=[[fb13item42]],["left"]=[[fb13_55]],["name"]=[[密道]],["permission"]=1,["right"]=[[fb13_61]],["rightDown"]=[[fb13_66]],["rightUp"]=[[fb13_57]],["stepMusic"]=[[jiaobu]]},["fb13_57"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb13_57]],["leftDown"]=[[fb13_56]],["name"]=[[密道]],["permission"]=1,["right"]=[[fb13_58]],["stepMusic"]=[[jiaobu]]},["fb13_58"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb13_58]],["item1"]=[[fb13item37]],["left"]=[[fb13_57]],["name"]=[[密道]],["permission"]=1,["right"]=[[fb13_59]],["stepMusic"]=[[jiaobu]]},["fb13_59"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb13_59]],["item1"]=[[fb13item42]],["item2"]=[[fb13item25]],["left"]=[[fb13_58]],["name"]=[[密道]],["permission"]=1,["right"]=[[fb13_60]],["stepMusic"]=[[jiaobu]]},["fb13_60"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb13_60]],["item1"]=[[fb13item34]],["item2"]=[[fb13item40]],["left"]=[[fb13_59]],["name"]=[[密道]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb13_61"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb13_61]],["left"]=[[fb13_56]],["name"]=[[密道]],["permission"]=1,["right"]=[[fb13_62]],["stepMusic"]=[[jiaobu]]},["fb13_62"]={["dsc"]=[[你的