=[[jiaobu]],["up"]=[[fb13_72]]},["fb13_72"]={["down"]=[[fb13_71]],["dsc"]=[[这是一座古洞所在，洞中有一张石床，两个石凳，里面似乎还有其他房间。]],["id"]=[[fb13_72]],["item1"]=[[wabaorenwu12]],["name"]=[[古洞]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb13_73]]},["fb13_73"]={["down"]=[[fb13_72]],["dsc"]=[[这是一座古洞所在，洞中有一张石床，两个石凳，里面似乎还有其他房间。]],["id"]=[[fb13_73]],["name"]=[[古洞]],["permission"]=2,["right"]=[[fb13_74]],["stepMusic"]=[[jiaobu]]},["fb13_74"]={["dsc"]=[[这是一座古洞所在，洞中有一张石床，两个石凳，里面似乎还有其他房间。]],["id"]=[[fb13_74]],["item1"]=[[wabaorenwu18]],["left"]=[[fb13_73]],["name"]=[[古洞]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb13_75"]={["dsc"]=[[嵩山山崖之上一处陡峭的峭壁。虽然看似陡峭，但却有不少可以落脚之处，似乎有人故意开凿出来。峭壁两旁生长着草木，也可用于攀爬。]],["id"]=[[fb13_75]],["leftDown"]=[[fb13_06]],["name"]=[[峭壁]],["permission"]=2,["role1"]=[[rybritem1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb13_76"]={["dsc"]=[[嵩山山崖之上一处陡峭的峭壁。虽然看似陡峭，但却有不少可以落脚之处，似乎有人故意开凿出来。峭壁两旁生长着草木，也可用于攀爬。]],["id"]=[[fb13_76]],["leftDown"]=[[fb13_75]],["name"]=[[峭壁]],["permission"]=2,["role1"]=[[rybritem2]],["stepMusic"]=[[jiaobu]]},["fb13_77"]={["dsc"]=[[一个存放着不少兵器的兵器库。里面的兵器都被整齐地摆放在武器架上。一名下人正在这里打扫。]],["id"]=[[fb13_77]],["name"]=[[兵器库]],["permission"]=2,["role1"]=[[rybrr77_01]],["role2"]=[[rybritem14]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_79]]},["fb13_78"]={["dsc"]=[[峭壁之上正对东升场所的凉亭，因为能将日升一览无余，因而称之为望日亭。亭中有一个石台，上面似乎摆放着什么东西。]],["id"]=[[fb13_78]],["leftDown"]=[[fb13_76]],["name"]=[[望日亭]],["permission"]=2,["right"]=[[fb13_79]],["role1"]=[[rybritem3]],["stepMusic"]=[[jiaobu]]},["fb13_79"]={["down"]=[[fb13_77]],["dsc"]=[[一个不大的广场，广场修建的十分平整。两旁设有石凳，可供人休息。]],["id"]=[[fb13_79]],["left"]=[[fb13_78]],["name"]=[[广场]],["permission"]=2,["right"]=[[fb13_80]],["role1"]=[[rybrr79_01]],["stepMusic"]=[[jiaobu]],["up"]=[[fb13_81]]},["fb13_80"]={["dsc"]=[[这里便是重光教其中一处分舵。分舵之内设施齐全，四通八达，是一处不错的避世之所。]],["id"]=[[fb13_80]],["left"]=[[fb13_79]],["name"]=[[重光分舵]],["permission"]=2,["rightUp"]=[[fb13_82]],["role1"]=[[rybrr80_01]],["stepMusic"]=[[jiaobu]]},["fb13_81"]={["down"]=[[fb13_79]],["dsc"]=[[重光弟子练武的场所。外人也可在此练武。重光弟子入教之前都需经过选拔，但具体选拔是什么，从无人得知。]],["id"]=[[fb13_81]],["name"]=[[练武场]],["permission"]=2,["role1"]=[[rybrr81_01]],["role2"]=[[rybrr81_02]],["stepMusic"]=[[jiaobu]]},["fb13_82"]={["dsc"]=[[一个青石铺成的石阶，笔直往上，一直通往最高处的天台。石阶两旁每隔一段距离便雕刻有石狮，形态各异，口中都含着石球。]],["id"]=[[fb13_82]],["leftDown"]=[[fb13_80]],["name"]=[[石阶]],["permission"]=2,["rightUp"]=[[fb13_84]],["stepMusic"]=[[jiaobu]]},["fb13_83"]={["dsc"]=[[这里是祭祀日神尧白的场所。尧白是重光教所崇拜的太阳之神，以男子之身现世，赋予人世生命，他的光芒普照大地，万物沐浴阳光之后，便能获得生机。]],["id"]=[[fb13_83]],["name"]=[[日坛]],["permission"]=2,["right"]=[[fb13_84]],["role1"]=[[rybrr83_01]],["role2"]=[[rybritem5]],["role3"]=[[rybritem15]],["stepMusic"]=[[jiaobu]]},["fb13_84"]={["dsc"]=[[一个青石铺成的石阶，笔直往上，一直通往最高处的天台。石阶两旁每隔一段距离便雕刻有石狮，形态各异，口中都含着石球。]],["id"]=[[fb13_84]],["left"]=[[fb13_83]],["leftDown"]=[[fb13_82]],["name"]=[[石阶]],["permission"]=2,["right"]=[[fb13_85]],["rightUp"]=[[fb13_86]],["stepMusic"]=[[jiaobu]]},["fb13_85"]={["dsc"]=[[这里是祭祀月神谦和的场所。谦和是重光教所崇拜的月亮之神，以女子之身现世，赋予人世情感，柔和的月光倾洒大地，万物便能获得灵性。]],["id"]=[[fb13_85]],["left"]=[[fb13_84]],["name"]=[[月坛]],["permission"]=2,["role1"]=[[rybrr85_01]],["role2"]=[[rybritem11]],["role3"]=[[rybritem16]],["stepMusic"]=[[jiaobu]]},["fb13_86"]={["dsc"]=[[重光分舵的正殿，是侍从商议大事的场所。正殿修建十分气派，左右梁柱之上各自雕刻着日月之神，正中红毯铺地，踩上去十分柔软。正殿深处是侍从的宝座，由纯银打造而成，雕工精致，侍从平时便在宝座之上传播教义。]],["id"]=[[fb13_86]],["leftDown"]=[[fb13_84]],["name"]=[[正殿]],["permission"]=2,["right"]=[[fb13_87]],["role1"]=[[rybrr86_01]],["role2"]=[[rybrr86_02]],["stepMusic"]=[[jiaobu]]},["fb13_87"]={["dsc"]=[[正殿之后的一个偏室，是用于忏悔自身罪孽的地方，也是清修的场所。重光弟子可在此引日月之泉的水洗涤自身，以清静身心。忏悔室之后还有一个密室，但大门却是紧闭着，无法打开。]],["id"]=[[fb13_87]],["left"]=[[fb13_86]],["name"]=[[忏悔室]],["permission"]=2,["role1"]=[[rybritem8]],["stepMusic"]=[[jiaobu]]}}00000